  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 The Prophet of Salvation: Isaiah$j$, $j${"readings": [{"title": "Isaiah 6 (King James Version)", "url": "/portal/bible/Isaiah/6"}, {"title": "Isaiah 9 (King James Version)", "url": "/portal/bible/Isaiah/9"}, {"title": "Isaiah 40 (King James Version)", "url": "/portal/bible/Isaiah/40"}], "body": "Read Isaiah 6, Isaiah 9:1 to 7 and Isaiah 40 in the King James Version. Then read this lesson.\n\nIsaiah served as a prophet in Judah for many years, in the days of kings such as Uzziah and Hezekiah, about seven hundred years before Christ. A prophet was a messenger who spoke for God, calling the people back to the covenant, warning of judgment, and giving hope. Isaiah saw the LORD high and lifted up in the temple and answered, Here am I; send me. His book warns Judah of the coming judgment, then turns in chapter 40 to a message of comfort. Isaiah speaks more about the coming Messiah than any other Old Testament prophet.\n\nKey words: prophet, holy, judgment, comfort, Messiah.\n\nYour task: (1) Tell what a prophet was. (2) Describe what Isaiah saw in chapter 6 and how he answered. (3) Write Isaiah 9:6 and say what it tells us about the child to come.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 4. We now move to the prophets. The Old Testament has sixteen books of prophecy, and we divide them into the major prophets and the minor prophets. Major and minor do not mean more or less important. They simply refer to the length of the books. Today we begin with the longest of the prophets, Isaiah.\n\nFirst, what is a prophet? A prophet is a messenger who speaks for God. Prophets did two things. They told forth God's message to their own generation, and sometimes they foretold what was coming. Their main work was to call God's people back to the covenant. When the people forgot the LORD, God sent prophets to warn them and to offer hope.\n\nIsaiah lived in Jerusalem about seven hundred years before Christ. He prophesied during the reigns of several kings of Judah. His call is in Isaiah chapter 6. In the year that King Uzziah died, Isaiah saw the Lord sitting upon a throne, high and lifted up. Angels cried, Holy, holy, holy, is the LORD of hosts: the whole earth is full of his glory. Isaiah was overwhelmed by his own sinfulness, and an angel touched his lips with a live coal from the altar. Then Isaiah heard the Lord ask, Whom shall I send, and who will go for us? Isaiah answered, Here am I; send me.\n\nMuch of the first part of Isaiah warns Judah of coming judgment because of their sin. But Isaiah is also known for hope. In chapter 9 he speaks of a child who will be born. Isaiah 9:6 says, For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace. Christians have always seen Jesus Christ in this prophecy.\n\nChapter 40 changes the tone. It begins, Comfort ye, comfort ye my people, saith your God. Looking ahead to the time of the exile, Isaiah promises that God will bring His people home. Isaiah 40:31 says, they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.\n\nYour task is to tell what a prophet was, describe Isaiah's vision and his answer, and write Isaiah 9:6 and say what it tells us about the coming child. Then take the four question check.\n\nWhen God asks who will go, be ready to say, here am I. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 The Prophet of Salvation: Isaiah$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 The Weeping Prophet: Jeremiah and Lamentations$j$, $j${"readings": [{"title": "Jeremiah 1 (King James Version)", "url": "/portal/bible/Jeremiah/1"}, {"title": "Jeremiah 29 (King James Version)", "url": "/portal/bible/Jeremiah/29"}, {"title": "Lamentations 3 (King James Version)", "url": "/portal/bible/Lamentations/3"}], "body": "Read Jeremiah 1, Jeremiah 29 and Lamentations 3 in the King James Version. Then read this lesson.\n\nJeremiah was called to be a prophet as a young man, about six hundred years before Christ. For more than forty years he warned Judah that Babylon would take the city if the people did not repent. They did not listen, and he was mocked, beaten and imprisoned. He is often called the weeping prophet. When Babylon destroyed Jerusalem, Jeremiah grieved over the city. Lamentations is a set of five poems of sorrow, traditionally credited to Jeremiah, that mourn the fall of Jerusalem while still holding on to hope in the faithfulness of God. Jeremiah also wrote to the exiles in Babylon and told them God had plans for their future.\n\nKey words: calling, repentance, exile, lament, new covenant.\n\nYour task: (1) Say what God told young Jeremiah in chapter 1. (2) Tell what Jeremiah told the exiles to do in Babylon. (3) Write Lamentations 3:22 and 23 in your own words.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Jeremiah was a young man when God called him. He said, Ah, Lord GOD! behold, I cannot speak: for I am a child. God answered, Say not, I am a child: for thou shalt go to all that I shall send thee, and whatsoever I command thee thou shalt speak. God did not ask Jeremiah to be strong on his own. He promised to be with him.\n\nJeremiah served for more than forty years during the last days of the kingdom of Judah, about six hundred years before Christ. His message was unpopular. He told the people that if they did not repent, Babylon would conquer Jerusalem. The kings and the false prophets said everything was fine, but Jeremiah told the truth. For that he was mocked, beaten, thrown into a cistern and put in prison. Because of his sorrow over his people he is often called the weeping prophet.\n\nJeremiah was right. In the days of King Zedekiah, Babylon took Jerusalem, burned the temple and carried many of the people into exile. The book of Lamentations was written in the aftermath. It is a set of five poems that grieve over the destroyed city. Yet right in the middle of the sorrow there is a light. Lamentations 3:22 and 23 say, It is of the LORD's mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness.\n\nJeremiah also wrote a letter to the exiles in Babylon. He told them not to give up, but to build houses, plant gardens, and pray for the city where they lived. Then he gave them a promise. Jeremiah 29:11 says, For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end. And the people were told in verse 13, And ye shall seek me, and find me, when ye shall search for me with all your heart.\n\nOne of the great promises in the book is in Jeremiah 31. God said He would make a new covenant with His people, unlike the one made at Sinai. He would write His law in their hearts. Christians understand that this new covenant is fulfilled through Jesus Christ.\n\nYour task is to say what God told Jeremiah in chapter 1, tell what he told the exiles to do, and put Lamentations 3:22 and 23 in your own words. Then take the four question check.\n\nGod's mercies are new every morning, even in the hardest days. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 The Weeping Prophet: Jeremiah and Lamentations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Visions of Glory: Ezekiel$j$, $j${"readings": [{"title": "Ezekiel 1 (King James Version)", "url": "/portal/bible/Ezekiel/1"}, {"title": "Ezekiel 34 (King James Version)", "url": "/portal/bible/Ezekiel/34"}, {"title": "Ezekiel 36 (King James Version)", "url": "/portal/bible/Ezekiel/36"}, {"title": "Ezekiel 37 (King James Version)", "url": "/portal/bible/Ezekiel/37"}], "body": "Read Ezekiel 1:1 to 3, Ezekiel 34, Ezekiel 36:24 to 28 and Ezekiel 37 in the King James Version. Then read this lesson.\n\nEzekiel was a priest who was carried to Babylon in the first deportation, before Jerusalem fell. God called him by the river Chebar and gave him amazing visions of His glory. His book has two main parts. In the first part he warns that Jerusalem will fall because of idolatry. After the city fell, his message turned to hope. God promised to gather His people, give them a new heart and a new spirit, and put His Spirit within them. The vision of the valley of dry bones in chapter 37 is a picture of God bringing Israel back to life.\n\nKey words: vision, glory, watchman, new heart, restoration.\n\nYour task: (1) Tell where Ezekiel was when God called him. (2) Describe the valley of dry bones. (3) Explain what a new heart means in Ezekiel 36:26.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Ezekiel was a priest, but he never served in the temple. When he was a young man, Babylon carried him away to a foreign land. There, by the river Chebar, the heavens opened and Ezekiel saw visions of God. These visions show the glory and majesty of the LORD, who is not limited to a building or a city. God was with His people even in exile.\n\nGod made Ezekiel a watchman. A watchman stands on the wall and warns the people when danger is coming. Ezekiel 33 says that if the watchman sees the sword coming and blows the trumpet, the people are responsible to listen. Ezekiel's first warnings said that Jerusalem would fall, because the people had filled the temple with idols. The people in exile did not want to believe it, but the news soon came that the city had been destroyed.\n\nAfter the fall of Jerusalem, Ezekiel's message turned to hope. In chapter 34 God promised to be the Shepherd who would search for His scattered sheep. In chapter 36 God made one of the great promises of the Old Testament. Ezekiel 36:26 says, A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh. And verse 27 says, And I will put my spirit within you, and cause you to walk in my statutes. God was promising not only to bring the people home but to change them from the inside.\n\nThen comes the most famous vision. In Ezekiel 37 the prophet was set down in a valley full of dry bones. God asked, Son of man, can these bones live? Ezekiel answered, O Lord GOD, thou knowest. At God's command Ezekiel prophesied, and the bones came together, flesh grew on them, and breath entered them. They stood up as an exceedingly great army. God explained that the bones were the whole house of Israel, and that He would bring them out of their graves and bring them home. Even a nation that felt dead could live again.\n\nThe book ends with a vision of a new temple and the words, The LORD is there. The God who seemed to be far away would one day dwell with His people again.\n\nYour task is to tell where Ezekiel was when God called him, describe the valley of dry bones, and explain what a new heart means. Then take the four question check.\n\nGod can bring life where everything seems dead. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Visions of Glory: Ezekiel$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Faith in the Fire: Daniel$j$, $j${"readings": [{"title": "Daniel 1 (King James Version)", "url": "/portal/bible/Daniel/1"}, {"title": "Daniel 3 (King James Version)", "url": "/portal/bible/Daniel/3"}, {"title": "Daniel 6 (King James Version)", "url": "/portal/bible/Daniel/6"}, {"title": "Daniel 7 (King James Version)", "url": "/portal/bible/Daniel/7"}], "body": "Read Daniel 1, Daniel 3, Daniel 6 and Daniel 7:13 and 14 in the King James Version. Then read this lesson.\n\nDaniel was taken to Babylon as a teenager and trained to serve in the king's court. He and his friends Shadrach, Meshach and Abednego refused to defile themselves with the king's food and later refused to bow to a golden image. The three friends were thrown into a fiery furnace and God delivered them. Daniel was thrown into the den of lions for praying to God, and God shut the lions' mouths. Daniel also interpreted dreams and received visions of kingdoms to come, which ended with the kingdom of God that will never be destroyed. Daniel is a book of courage for people living in a culture that does not follow God.\n\nKey words: faith, courage, integrity, kingdom, deliverance.\n\nYour task: (1) Name the three friends who were thrown into the furnace. (2) Tell why Daniel was thrown to the lions. (3) Say what Daniel 7:14 teaches about the kingdom of God.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "The last of the major prophets is Daniel, and it is one of the most loved books in the Bible. It is a book about young people who stayed faithful to God in a foreign land.\n\nDaniel was probably a teenager when Babylon took him away from Jerusalem. The king chose Daniel and three other young men, Hananiah, Mishael and Azariah, to be trained for the king's service. They were given new names in Babylon. Daniel was called Belteshazzar and the three friends were called Shadrach, Meshach and Abednego. In chapter 1 we read that Daniel purposed in his heart that he would not defile himself with the king's food. He asked to eat vegetables and drink water, and God blessed him with health and wisdom.\n\nIn chapter 3 King Nebuchadnezzar set up a huge golden image and commanded everyone to bow down. Shadrach, Meshach and Abednego refused. They told the king that the God they served was able to deliver them, and that even if He did not, they would not worship the image. The king had them thrown into a furnace heated seven times hotter than normal. But the king saw four men walking in the fire, and the fourth looked like the Son of God. They came out without even the smell of smoke on them.\n\nDaniel stayed in service under later kings. In chapter 6, under King Darius, jealous officials tricked the king into signing a law that no one could pray to anyone except the king for thirty days. Daniel knew the law was signed, and he went home and prayed three times a day with his windows open toward Jerusalem. He was thrown to the lions, but God sent an angel and shut the lions' mouths. In the morning the king found Daniel alive.\n\nDaniel also received visions of the future. In chapter 2 he interpreted a dream of a great statue that represented kingdoms of the world. In chapter 7 he saw one like the Son of man coming with the clouds of heaven. Daniel 7:14 says, And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed. Earthly empires rise and fall, but God's kingdom will last forever.\n\nYour task is to name the three friends, tell why Daniel was thrown to the lions, and explain what Daniel 7:14 teaches. Then take the four question check and the Unit 4 quiz.\n\nStand for what is right even when you stand alone. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Faith in the Fire: Daniel$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: A Prophet's Message$j$, $j${"prompt": "Choose one of the four prophets in this unit: Isaiah, Jeremiah, Ezekiel or Daniel. Write one paragraph of 150 to 200 words. Tell who the prophet was, what message God gave the prophet, and how the people responded. Then explain one lesson from the prophet's life that a student today can use. Quote at least one verse from the King James Version.", "rubric": "Total 100. Accurate account of the prophet and the message: 30. Describes how the people responded: 20. Explains one lesson for today, with a quoted King James Version verse: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: A Prophet's Message$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Standing for What Is Right$j$, $j${"prompt": "Daniel and his friends stood firm when everyone around them did otherwise. Describe a time you had to stand for what was right, or a time you wish you had. Explain what courage looks like for a student your age. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Standing for What Is Right$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: The Prophet of Salvation: Isaiah$j$, $j${"questions": [{"q": "What was the main work of an Old Testament prophet?", "options": ["Speaking God's message and calling the people back to the covenant", "Keeping the temple records", "Building cities", "Leading armies"]}, {"q": "What did Isaiah say when God asked whom He should send?", "options": ["Let someone else go", "Send my brother", "Here am I; send me", "I am not able"]}, {"q": "What does Isaiah 9:6 promise?", "options": ["A child who would be born and a son who would be given", "A famine", "A flood", "A new temple of gold"]}, {"q": "How does Isaiah 40 begin?", "options": ["With the words, Comfort ye my people", "With a warning of war", "With a list of kings", "With a curse"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Prophet of Salvation: Isaiah$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,0}'::int[], array[$j$A prophet was a messenger who spoke for God.$j$,$j$Isaiah answered, Here am I; send me (Isaiah 6:8).$j$,$j$Isaiah 9:6 speaks of a child born and a son given, whose name is Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.$j$,$j$Isaiah 40 begins with a message of comfort.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Prophet of Salvation: Isaiah$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: The Weeping Prophet: Jeremiah and Lamentations$j$, $j${"questions": [{"q": "Why is Jeremiah often called the weeping prophet?", "options": ["He sang sad songs", "He was a poor man", "He lived in a cave", "He grieved over the sin and coming fall of his people"]}, {"q": "Which nation destroyed Jerusalem in Jeremiah's time?", "options": ["Egypt", "Rome", "Assyria", "Babylon"]}, {"q": "What does Lamentations 3:22 and 23 say about the LORD's mercies?", "options": ["They have an end", "They are only for kings", "They fail in the evening", "They are new every morning"]}, {"q": "What did God promise to do in the new covenant of Jeremiah 31?", "options": ["End all prophecy", "Remove the temple", "Send them back to Egypt", "Write His law in their hearts"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Weeping Prophet: Jeremiah and Lamentations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,3,3}'::int[], array[$j$Jeremiah mourned for Judah as he warned of the coming judgment.$j$,$j$Babylon took Jerusalem and carried Judah into exile.$j$,$j$His compassions fail not; they are new every morning.$j$,$j$God promised to put His law in their inward parts and write it in their hearts.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Weeping Prophet: Jeremiah and Lamentations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Visions of Glory: Ezekiel$j$, $j${"questions": [{"q": "Where was Ezekiel when God called him?", "options": ["On Mount Sinai", "In the temple at Jerusalem", "In Egypt", "By the river Chebar in Babylon"]}, {"q": "What is a watchman's job in Ezekiel?", "options": ["To lead the army", "To guard the ark", "To collect taxes", "To warn the people of danger"]}, {"q": "What did God show Ezekiel in chapter 37?", "options": ["A burning mountain", "A valley of dry bones coming to life", "A golden idol", "A great flood"]}, {"q": "What does God promise in Ezekiel 36:26?", "options": ["A new heart and a new spirit", "A new city of stone", "A new king", "A new law of fines"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Visions of Glory: Ezekiel$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,1,0}'::int[], array[$j$Ezekiel was among the exiles by the river Chebar in the land of the Chaldeans.$j$,$j$The watchman blows the trumpet to warn the people.$j$,$j$The vision pictured God restoring Israel to life.$j$,$j$God promised to give a new heart and put a new spirit within His people.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Visions of Glory: Ezekiel$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Faith in the Fire: Daniel$j$, $j${"questions": [{"q": "Which three friends were thrown into the fiery furnace?", "options": ["Peter, James and John", "Shem, Ham and Japheth", "Gad, Asher and Dan", "Shadrach, Meshach and Abednego"]}, {"q": "Why was Daniel thrown into the den of lions?", "options": ["He prayed to God against the king's law", "He stole food", "He refused to wear a crown", "He fought a soldier"]}, {"q": "What did the king see in the furnace?", "options": ["Only the three friends", "A great wall", "No one", "Four men walking in the fire"]}, {"q": "What does Daniel 7:14 teach about God's kingdom?", "options": ["It is for one nation only", "It will end with Babylon", "It belongs only to Persia", "It is an everlasting dominion that will not be destroyed"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Faith in the Fire: Daniel$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,3}'::int[], array[$j$Shadrach, Meshach and Abednego refused to bow to the golden image.$j$,$j$Daniel kept praying to God even after the law was signed.$j$,$j$Nebuchadnezzar saw four men loose in the fire, and the fourth was like the Son of God.$j$,$j$The kingdom given to the Son of man is everlasting and shall not be destroyed.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Faith in the Fire: Daniel$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: The Major Prophets, Isaiah to Daniel$j$, $j${"questions": [{"q": "Which prophet answered, Here am I; send me?", "options": ["Daniel", "Ezekiel", "Isaiah", "Jeremiah"]}, {"q": "Which prophet is called the weeping prophet?", "options": ["Jeremiah", "Ezekiel", "Isaiah", "Daniel"]}, {"q": "Lamentations is a book of:", "options": ["Genealogies", "Proverbs", "Laws", "Poems of sorrow over Jerusalem"]}, {"q": "What did the valley of dry bones picture?", "options": ["The restoration of Israel to life", "A famine", "The building of the temple", "A war that Israel would win"]}, {"q": "Where were Daniel and his friends taken as young men?", "options": ["Babylon", "Rome", "Assyria", "Egypt"]}, {"q": "The prophets called God's people to:", "options": ["Stop worshipping altogether", "Fight their neighbors", "Worship idols", "Return to the covenant and trust the LORD"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: The Major Prophets, Isaiah to Daniel$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,0,0,3}'::int[], array[$j$Isaiah answered God's call in Isaiah 6:8.$j$,$j$Jeremiah grieved over Judah as he warned of the fall of Jerusalem.$j$,$j$Lamentations mourns the fall of Jerusalem and still trusts the LORD's mercies.$j$,$j$God was showing that He would restore the nation to life.$j$,$j$They were carried from Judah to Babylon.$j$,$j$The prophets warned, corrected and encouraged the people to return to God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: The Major Prophets, Isaiah to Daniel$j$ on conflict (item_id) do nothing;
